def catalan_number(n):
    # Function to calculate factorial
    def factorial(num):
        if num == 0 or num == 1:
            return 1
        result = 1
        for i in range(2, num + 1):
            result *= i
        return result

    # Using the formula: C(n) = (2n)! / ((n + 1)! * n!)
    return factorial(2 * n) // (factorial(n + 1) * factorial(n))

